136:   game.creatures.push(child); game.selected=child.id; closeModal(); if(mode==='habitat') { world.addCreature(child,{position:[0,0,0]}); world.setSelected(child.id) }
137:   persist(); renderRoster(); renderProfile(); toast(`${child.name} hatched with ${mutations.length} mutated gene${mutations.length===1?'':'s'}!`)
138: }
139: function renameDialog() {
140:   const c=selected(); showModal(`<button class="modal-close" data-action="close">×</button><div class="eyebrow">CREATURE DOSSIER</div><h2>Rename specimen</h2><label class="field-label">SPECIMEN NAME<input id="rename-input" maxlength="20" value="${esc(c.name)}"></label><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="rename-confirm">SAVE NAME</button></div>`)
141:   $('#rename-input').focus(); $('#rename-input').select()
142: }
143: function rename() { const input=$('#rename-input'), name=input?.value.trim(); if(!name)return toast('A name cannot be empty.'); selected().name=name; closeModal(); renderRoster(); renderProfile(); persist(); toast('Specimen renamed.') }
144: function arenaDialog() {
